wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5658202078410750215)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Execute Wizard Cancellation'
,p_static_id=>'execute-wizard-cancellation'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF APEX_COLLECTION.COLLECTION_EXISTS(''ONBOARDING_COLLECTION'') THEN',
'    APEX_COLLECTION.DELETE_COLLECTION(''ONBOARDING_COLLECTION'');',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5654972282856651610)
,p_internal_uid=>5658202078410750215
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5512321802505618344)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Docs'
,p_static_id=>'upload-docs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob BLOB;',
'BEGIN',
'    IF :P10_PASSPORT IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_PASSPORT;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 1,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
'    END IF;',
'',
'    IF :P10_CONTRACT_BLOB IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_CONTRACT_BLOB;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 2,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
'    END IF;',
'',
'    IF :P10_TAX_FORM_BLOB IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_TAX_FORM_BLOB;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 3,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>5512321802505618344
);
end;
/
